mapper.select:
SELECT r.id FROM backfill_run r
WHERE r.state = 'RUNNING' AND r.from_year = #{fromYear} AND r.to_year = #{toYear}
  AND r.snapshot_date = #{snapshotDate} AND r.files_total = #{filesTotal}
  AND (SELECT min(f.idx) FROM backfill_file f WHERE f.run_id = r.id) = #{firstIdx}
ORDER BY r.id LIMIT 1
